def prime_fib(n):
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def fib_gen():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    fib_gen = fib_gen()
    count = 0
    for fib in fib_gen:
        if is_prime(fib):
            count += 1
            if count == n:
                return fib

